{
  "findings": [
    {
      "check_id": "CKV_AZURE_10",
      "title": "Storage account allows non-HTTPS traffic",
      "resource": "azurerm_storage_account.media_storage",
      "severity": "HIGH",
      "explanation": "The attribute 'enable_https_traffic_only' is set to false, allowing clients to access the storage account over unencrypted HTTP connections, which exposes data in transit to interception."
    },
    {
      "check_id": "CKV_AZURE_11",
      "title": "Storage account supports weak TLS versions",
      "resource": "azurerm_storage_account.media_storage",
      "severity": "MEDIUM",
      "explanation": "The 'min_tls_version' is set to 'TLS1_0', which is deprecated and vulnerable to known attacks. It should be updated to at least 'TLS1_2' to ensure secure communication."
    }
  ],
  "patched_code": "resource \"azurerm_storage_account\" \"media_storage\" {\n  name                     = \"corpmediastorage${random_string.storage_suffix.result}\"\n  resource_group_name      = azurerm_resource_group.corporate_media_streaming.name\n  location                 = azurerm_resource_group.corporate_media_streaming.location\n  account_tier             = \"Standard\"\n  account_replication_type = \"GRS\"\n  enable_https_traffic_only = true\n  min_tls_version = \"TLS1_2\"\n  blob_properties {\n    versioning_enabled = true\n  }\n}",
  "fix_summary": "Enabled HTTPS-only traffic by setting 'enable_https_traffic_only' to true and upgraded the minimum TLS version from 'TLS1_0' to 'TLS1_2' to enforce secure communication protocols."
}
